%[text] # Check simulation behavior of Road Grade Profile block
%[text] 1. Specify elevation profile, and derive road grade profile.
%[text] 2. Use the derived road grade profile in the Road Grade Profile block, run simulation, and get the simulated elevation result.
%[text] 3. Compare the specified elevation profile and the simulated one. \
%[text] ## Setting
length_unit = "m";

elevation_profile = table( ...
  simscape.Value([0 50 100,  200 250 300,  400 450 500,  600 650 700,  800 850 900], length_unit)', ...
  simscape.Value([0 0 0, 1 1 1, 3 3 3, 6 6 6, 2 2 2], length_unit)', ...
  VariableNames = ["HorizontalDistance", "Elevation"] );

dx = 0.5;
%[text] ## Derivation / Preprocess
x_1 = value(elevation_profile.HorizontalDistance(1), length_unit);
x_end = value(elevation_profile.HorizontalDistance(end), length_unit);

% Horizontal distance for vertical profile
refined_x = x_1 : dx : x_end;

refined_elevation = interp1( ...
  value(elevation_profile.HorizontalDistance, length_unit), ...
  value(elevation_profile.Elevation, length_unit), refined_x, "makima");

dzdx_vec = gradient(refined_elevation, dx);

% Road grade profile (percent)
refined_grade_pct = 100 * tan(dzdx_vec);
%[text] 
fig = figure; %[output:1dbdb129]
fig.Position(3:4) = [800, 400]; %[output:1dbdb129]
tl = tiledlayout(fig, 2, 1, TileSpacing="tight"); %[output:1dbdb129]

ax = nexttile(tl); %[output:1dbdb129]
plot(ax, refined_x, refined_elevation, LineWidth=2) %[output:1dbdb129]
hold(ax, "on");  axis(ax, "padded");  grid(ax, "on") %[output:1dbdb129]
sc = scatter(ax, value(elevation_profile.HorizontalDistance, length_unit), value(elevation_profile.Elevation, length_unit), 100); %[output:1dbdb129]
sc.Marker = "x";  sc.LineWidth = 2; %[output:1dbdb129]
title(ax, "Specified elevation") %[output:1dbdb129]
ylabel(ax, "(" + string(unit(elevation_profile.Elevation)) + ")") %[output:1dbdb129]

ax = nexttile(tl); %[output:1dbdb129]
plot(ax, refined_x, refined_grade_pct, LineWidth=2) %[output:1dbdb129]
hold(ax, "on");  axis(ax, "padded");  grid(ax, "on") %[output:1dbdb129]
title(ax, "Derived road grade") %[output:1dbdb129]
ylabel(ax, "(%)") %[output:1dbdb129]
xlabel(ax, "Horizontal distance, x (" + length_unit + ")") %[output:1dbdb129]
%%
%[text] ## Simulation
model_name = "HarnessModel_CustomRoadGradeProfile";
load_system(model_name)
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime=bevutil1.CodeUtil.stringify(refined_x(end)));
setb = @setBlockParameter;
sim_in = setb(sim_in, model_name+"/Curvilinear Speed", "constant", "1");
sim_in = setb(sim_in, model_name+"/Curvilinear Speed", "constant_unit", length_unit+"/s");
sim_in = setb(sim_in, model_name+"/Road", "x_vector", bevutil1.CodeUtil.stringify(refined_x));
sim_in = setb(sim_in, model_name+"/Road", "x_vector_unit", length_unit);
sim_in = setb(sim_in, model_name+"/Road", "grade_vector", bevutil1.CodeUtil.stringify(refined_grade_pct));
sim_in = setb(sim_in, model_name+"/Road", "profile_interp_method", "simscape.enum.interpolation.smooth");
sim_in = setb(sim_in, model_name+"/Road", "initial_position", "0");
sim_in = setb(sim_in, model_name+"/Road", "initial_position_unit", length_unit);
sim_in = setb(sim_in, model_name+"/Road", "left_elevation", "0");
sim_in = setb(sim_in, model_name+"/Road", "left_elevation_unit", length_unit);
sim_out = sim(sim_in);
result = extractTimetable(sim_out.logsout);
%[text] 
% Road grade data table
RG_prep = timetable(seconds(refined_x'), refined_grade_pct', VariableNames="f");
RG_sim = timetable(result.Time, result.("Grade percent"), VariableNames="f");
% Union of row times. Linearly resample.
SyncedRoadGrade = synchronize(RG_prep, RG_sim, "union", "linear");
SyncedRoadGrade.Properties.VariableNames = ["Prep", "Sim"];
road_grade_diff = SyncedRoadGrade.Sim - SyncedRoadGrade.Prep;
%[text] 
% Elevation data table
E_prep = timetable(seconds(refined_x'), refined_elevation', VariableNames="z");
E_sim = timetable(result.Time, result.("Elevation"), VariableNames="z");
% Union of row times. Linearly resample.
SyncedElevation = synchronize(E_prep, E_sim, "union", "linear");
SyncedElevation.Properties.VariableNames = ["Prep", "Sim"];
elevation_diff = SyncedElevation.Sim - SyncedElevation.Prep;
%%
%[text] ## Visualization
ax = axes(figure); %[output:1f34f0bc]
plot(ax, SyncedRoadGrade.Time, SyncedRoadGrade.Prep, LineWidth=4) %[output:1f34f0bc]
hold(ax, "on") %[output:1f34f0bc]
plot(ax, SyncedRoadGrade.Time, SyncedRoadGrade.Sim, LineWidth=1.5) %[output:1f34f0bc]
grid(ax, "on") %[output:1f34f0bc]
legend(ax, ["Prep", "Simulated"], Location="best") %[output:1f34f0bc]
xlabel(ax, "Time (s)") %[output:1f34f0bc]
ylabel(ax, "(%)") %[output:1f34f0bc]
title(ax, "Road grade") %[output:1f34f0bc]
ax = axes(figure); %[output:1046eeca]
plot(ax, SyncedRoadGrade.Time, road_grade_diff, LineWidth=1.5) %[output:1046eeca]
hold(ax, "on") %[output:1046eeca]
grid(ax, "on") %[output:1046eeca]
xlabel(ax, "Time (s)") %[output:1046eeca]
ylabel(ax, "(%)") %[output:1046eeca]
title(ax, "Road grade difference: Sim - Prep") %[output:1046eeca]
ax = axes(figure); %[output:7aa71394]
plot(ax, SyncedElevation.Time, SyncedElevation.Prep, LineWidth=4) %[output:7aa71394]
hold(ax, "on") %[output:7aa71394]
plot(ax, SyncedElevation.Time, SyncedElevation.Sim, LineWidth=1.5) %[output:7aa71394]
grid(ax, "on") %[output:7aa71394]
legend(ax, ["Prep", "Simulated"], Location="best") %[output:7aa71394]
xlabel(ax, "Time (s)") %[output:7aa71394]
ylabel(ax, "(" + length_unit + ")") %[output:7aa71394]
title(ax, "Elevation") %[output:7aa71394]
ax = axes(figure); %[output:93a4a18b]
plot(ax, SyncedElevation.Time, elevation_diff, LineWidth=1.5) %[output:93a4a18b]
hold(ax, "on") %[output:93a4a18b]
grid(ax, "on") %[output:93a4a18b]
xlabel(ax, "Time (s)") %[output:93a4a18b]
ylabel(ax, "(" + length_unit + ")") %[output:93a4a18b]
title(ax, "Elevation difference: Sim - Prep") %[output:93a4a18b]
